"""Build data/facts.json: grounding pack for Tasan's AI analyst (atomic, sourced facts).
Every numeric fact carries `checks` = machine-verifiable pointers into data/csv/*.csv or data/hero.json; run scripts/check_facts.py.
Values are typed in here from our own CSV/MD outputs (all built 2026-11-14); check_facts.py re-reads the CSVs and fails on any mismatch."""
import json, os
D=os.path.join(os.path.dirname(__file__),'..')
S='https://files.hackjunction.app/resources/Kansallinen_syopastrategia_2026_2035_FINAL.pdf'
RM='https://files.hackjunction.app/resources/Kansallinen_syopastrategia_toimeenpanon_tiekartta_2026_2031.pdf'
THL='https://www.julkari.fi/server/api/core/bitstreams/de33d584-bdce-40a1-b100-df48c4906a49/content'
THL17='https://www.julkari.fi/server/api/core/bitstreams/c0c8c67d-3b8b-4016-ad52-b40682713441/content'
R24='https://syoparekisteri.fi/assets/files/2024/12/Keuhkosyopa_Suomessa.pdf'
R26='https://syoparekisteri.fi/assets/themes/ssy3/factsheets/keuhkosyoparaportti.html'
SOT='https://sotkanet.fi/sotkanet/en/metadata/indicators/'
SF='https://pxdata.stat.fi/PXWeb/api/v1/fi/StatFin/ksyyt/13u5.px'
FI='Finland'
def reg(name,code): return {'name':name,'code':code}
LAP=reg('Lapland wellbeing services county','21'); VK=reg('Vantaa and Kerava wellbeing services county','04')
YN=reg('North Finland collaborative area (Pohjois-Suomi YTA)','YTA-POHJOIS'); YS=reg('South Finland collaborative area (Etelä-Suomi YTA)','YTA-ETELA')
YW=reg('West Finland collaborative area (Länsi-Suomi YTA)','YTA-LANSI'); YI=reg('Inland Finland collaborative area (Sisä-Suomi YTA)','YTA-SISA')
facts=[]
def F(id,stage,goal,en,fi,value,unit,region,years,src,table,mtype,caveat,pop=None,checks=None):
    facts.append(dict(id=id,statement_en=en,statement_fi=fi,value=value,unit=unit,region=region,years=years,population=pop,pathway_stage=stage,goal_link=goal,
                      source_url=src,source_table=table,measure_type=mtype,caveat=caveat,checks=checks or []))
def C(csv,col,expect,**where): return {'csv':csv,'where':where,'col':col,'expect':expect}
def CH(path,expect): return {'hero':path,'expect':expect}
G3='Goal 3 (strategy p.5)'; G3a='Goal 3 indicator 1 proxy (5-yr survival of poor-prognosis cancers; strategy p.5)'; G3c='Goal 3 indicator 3 proxy (treatment within target times; strategy p.5)'
G2='Goal 2 context (strategy p.5) - NOT Goal 3'; DQ='Data quality (relates to strategy sub-goal 3.2 registry coverage 90%, S p.36) - not a Goal 3 headline indicator'
CRUDE='Crude registry share (not age- or stage-adjusted; stage missing for 47.7% nationally); depends on how each region records treatment; residents of the county, not the treating hospital.'
# ---------------- policy
